"""Cut licensed (Wikimedia Commons) video excerpts into engine/public/<topic>/ as mp4 (H.264, 30 fps) + wav (48 kHz),
and log title / author / licence / source times in engine/public/<topic>/_clips.json (the clip twin of _commons.json).
Each excerpt keeps PAD seconds either side, so in a script its speech runs from PAD to PAD + (t1 - t0).
Usage: python tools/cc_clips.py <folder with the downloaded originals>   (edit CLIPS below; already-cut files are skipped)."""
import json, subprocess
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
OUT = ROOT / "engine/public/captchas"
PAD = 0.3
UA = "All-in-research/1.0 (quartz video project)"
import sys
LOCAL = Path(sys.argv[1]) if len(sys.argv) > 1 else None  # folder holding downloaded originals (Commons file names); http seeking into webm fails
WM15 = {"title": "File:Wikimania 2015 - Luis Von Ahn - Bringing Free Education to the World.webm", "author": "Wikimedia México",
        "licence": "CC BY-SA 3.0", "url": "https://upload.wikimedia.org/wikipedia/commons/5/5b/Wikimania_2015_-_Luis_Von_Ahn_-_Bringing_Free_Education_to_the_World.webm",
        "page": "https://commons.wikimedia.org/wiki/File:Wikimania_2015_-_Luis_Von_Ahn_-_Bringing_Free_Education_to_the_World.webm"}
V3 = {"title": "File:Introducing reCAPTCHA v3.webm", "author": "Google Search Central", "licence": "CC BY 3.0",
      "url": "https://upload.wikimedia.org/wikipedia/commons/f/f1/Introducing_reCAPTCHA_v3.webm",
      "page": "https://commons.wikimedia.org/wiki/File:Introducing_reCAPTCHA_v3.webm"}
# CCC talks: CC BY 4.0. Times are in the h264-hd mp4, which runs ~15-18 s later than the opus used for transcripts (intro):
# opus + 15.0 (34C3 9077), + 17.7 (36C3 10936), + 18.0 (35C3cw 32). (licence in the media.ccc.de page + mp4 metadata). Cut over http from the h264-hd mp4 (mp4 seeks fine).
S34 = {"title": "Humans as Software Extensions (34C3, talk 9077)", "author": "Sebastian Schmieg · Chaos Computer Club (media.ccc.de)",
       "licence": "CC BY 4.0", "url": "https://cdn.media.ccc.de/congress/2017/h264-hd/34c3-9077-eng-Humans_as_software_extensions.mp4",
       "page": "https://media.ccc.de/v/34c3-9077-humans_as_software_extensions", "remote": True}
F36 = {"title": "Inside the Fake Like Factories (36C3, talk 10936)", "author": "Svea Eckert, Philip Kreissel, Dennis Tatang · Chaos Computer Club (media.ccc.de)",
       "licence": "CC BY 4.0", "url": "https://cdn.media.ccc.de/congress/2019/h264-hd/36c3-10936-eng-Inside_the_Fake_Like_Factories.mp4",
       "page": "https://media.ccc.de/v/36c3-10936-inside_the_fake_like_factories", "remote": True}
K35 = {"title": "Toll of personal privacy in 2018 (35C3 Chaos West, talk 32)", "author": "Kirils Solovjovs · Chaos Computer Club (media.ccc.de)",
       "licence": "CC BY 4.0", "url": "https://cdn.media.ccc.de/congress/35C3-chaoswest/h264-hd/35c3-chaoswest-32-eng-Toll_of_personal_privacy_in_2018_hd.mp4",
       "page": "https://media.ccc.de/v/35c3chaoswest-32-toll-of-personal-privacy-in-2018", "remote": True}
CLIPS = {  # name: (source, t0, t1, words)
    "cc_wm15_annoying": (WM15, 20.50, 29.20, "How many of you found it really annoying? Excellent. Okay. Well, I invented that. Sorry."),
    "cc_wm15_feelbad": (WM15, 84.35, 96.30, "And if you multiply 10 seconds by 200 million, you get that humanity as a whole is wasting about 500,000 hours every day typing these annoying CAPTCHAs because of me. So, I started feeling bad."),
    "cc_wm15_free": (WM15, 561.95, 568.85, "So, what I wanted to do is I wanted to make something that would teach people languages, but it was entirely free. And this is what we did with Duolingo."),
    "cc_v3_bots": (V3, 0.60, 9.10, "If you have a website, you need to protect your users from bots. Bots are trying leaked passwords, hosting spam, and scraping your content."),
    "cc_v3_score": (V3, 18.45, 25.55, "reCAPTCHA v3 does away with the need for interactive tests and gives you a score to let you know when you have risky traffic."),
    "cc_v3_signals": (V3, 107.30, 115.80, "reCAPTCHA's adaptive risk analysis engine takes in various signals about the interaction and predicts the likelihood that the request was generated by a bot."),
    "cc_v3_catfood": (V3, 89.20, 92.90, "Here was a bot posting a review for a competitor's cat food."),
    "cc_v3_places": (V3, 116.30, 125.10, "It works best with context about how both humans and bots interact with your website, so for best performance, include reCAPTCHA in many places."),
    # v3 of the full cut (owner TOP RULE 2026-10-08: news clips out, CC only). Windows are loose; beats trim by word timings.
    "cc_wm15_scalpers": (WM15, 50.2, 63.6, "So, for example, in the case of Ticketmaster, the reason you have to type these characters is to prevent scalpers from writing a program that can buy millions of tickets two at a time."),
    "cc_wm15_brain": (WM15, 102.6, 115.1, "See, during those 10 seconds, while you're typing a CAPTCHA, your brain is doing something amazing. Your brain is doing something that computers cannot yet do."),
    "cc_wm15_agree": (WM15, 250.3, 258.2, "And if we repeat this process to like 10 different people, and they all agree on what the new word is, then we get one more word digitized with very high accuracy."),
    "cc_wm15_books": (WM15, 258.4, 272.9, "It has been very successful. Today, this is digitizing approximately 100 million words a day, which is the equivalent of about 2 million books a year."),
    "cc_wm15_billion": (WM15, 343.0, 356.4, "This is 1.1 billion. This is the total number of distinct people that have ever helped us digitize at least one word out of a book through the system. It's about 15% of the world's population."),
    "cc_v3_checkbox": (V3, 9.6, 26.0, "The reCAPTCHA I'm not a robot checkbox changed the way to protect your websites, but its one-time verification doesn't fit every use case. reCAPTCHA v3 does away with the need for interactive tests and gives you a score to let you know when you have risky traffic."),
    "cc_s34_history": (S34, 963.2, 986.9, "So, if you look at it, captchas started as a technique to merely prevent spam. And then, they kind of morphed into a method for deciphering house numbers and transcribing books. And then, lately, it's become a means of teaching image recognition to AI software."),
    "cc_s34_lawsuit": (S34, 998.4, 1011.4, "And she claimed that Google operates a highly profitable transcription business built upon free labor, which it deceptively and unfairly obtains from unwitting website users."),
    "cc_s34_unpaid": (S34, 863.6, 886.4, "So, you can automate as much as you want, but at some point you will have to train and especially maintain the machines and the software. So, I would say AI creates yet another layer of badly or unpaid care and maintenance work, which is often invisible on purpose."),
    "cc_k35_bot": (K35, 954.8, 970.6, "So I was accepting and honoring all cookies before, and now I only accept temporarily first-party cookies. And big tracking giants do not like that. So they make my life difficult. They think I'm a bot. I don't have any internet history associated with me."),
    "cc_f36_maria": (F36, 300.4, 318.8, "So Maria is a former police officer. And as money is always short, she is clicking Facebook likes for money. So she earns between two cents and six cents per like."),
}

log_path = OUT / "_clips.json"
log = json.loads(log_path.read_text(encoding="utf-8")) if log_path.exists() else {}
for name, (src, t0, t1, words) in CLIPS.items():
    mp4, wav = OUT / f"{name}.mp4", OUT / f"{name}.wav"
    s, d = max(0.0, t0 - PAD), (t1 - t0) + 2 * PAD
    if not mp4.exists():
        subprocess.run(["ffmpeg", "-loglevel", "error", "-y", *([] if LOCAL and not src.get("remote") else ["-user_agent", UA]), "-ss", f"{s:.2f}", "-i", str(LOCAL / src["url"].rsplit("/", 1)[1]) if LOCAL and not src.get("remote") else src["url"], "-t", f"{d:.2f}",
                        "-vf", "scale=1920:1080:force_original_aspect_ratio=decrease,pad=1920:1080:(ow-iw)/2:(oh-ih)/2,fps=30",
                        "-c:v", "libx264", "-crf", "18", "-preset", "medium", "-pix_fmt", "yuv420p", "-c:a", "aac", "-b:a", "160k", str(mp4)], check=True)
    if not wav.exists():
        subprocess.run(["ffmpeg", "-loglevel", "error", "-y", "-i", str(mp4), "-vn", "-ar", "48000", "-ac", "2", str(wav)], check=True)
    log[name] = {**{k: src[k] for k in ("title", "author", "licence", "page")}, "source_from": round(s, 2), "source_to": round(s + d, 2),
                 "speech_from": PAD if t0 >= PAD else t0, "speech_to": round((PAD if t0 >= PAD else t0) + t1 - t0, 2), "words": words}
    print("ok", name, f"{d:.1f}s")
log_path.write_text(json.dumps(log, ensure_ascii=False, indent=1), encoding="utf-8")
